57	/**
58	 * Get axis scale extent before niced.
59	 * Item of returned array can only be number (including Infinity and NaN).
60	 *
61	 * Caution:
62	 * Precondition of calling this method:
63	 * The scale extent has been initialized using series data extent via
64	 * `scale.setExtent` or `scale.unionExtentFromData`;
65	 */
66	export function getScaleExtent(scale: Scale, model: AxisBaseModel) {
67	    const scaleType = scale.type;
68	    const rawExtentResult = ensureScaleRawExtentInfo(scale, model, scale.getExtent()).calculate();
69	
70	    scale.setBlank(rawExtentResult.isBlank);
71	
72	    let min = rawExtentResult.min;
73	    let max = rawExtentResult.max;
74	
75	    // If bars are placed on a base axis of type time or interval account for axis boundary overflow and current axis
76	    // is base axis
77	    // FIXME
78	    // (1) Consider support value axis, where below zero and axis `onZero` should be handled properly.
79	    // (2) Refactor the logic with `barGrid`. Is it not need to `makeBarWidthAndOffsetInfo` twice with different extent?
80	    //     Should not depend on series type `bar`?
81	    // (3) Fix that might overlap when using dataZoom.
82	    // (4) Consider other chart types using `barGrid`?
83	    // See #6728, #4862, `test/bar-overflow-time-plot.html`
84	    const ecModel = model.ecModel;
85	    if (ecModel && (scaleType === 'time' /* || scaleType === 'interval' */)) {
86	        const barSeriesModels = prepareLayoutBarSeries('bar', ecModel);
87	        let isBaseAxisAndHasBarSeries = false;
88	
89	        zrUtil.each(barSeriesModels, function (seriesModel) {
90	            isBaseAxisAndHasBarSeries = isBaseAxisAndHasBarSeries || seriesModel.getBaseAxis() === model.axis;
91	        });
92	
93	        if (isBaseAxisAndHasBarSeries) {
94	            // Calculate placement of bars on axis. TODO should be decoupled
95	            // with barLayout
96	            const barWidthAndOffset = makeColumnLayout(barSeriesModels);
97	
98	            // Adjust axis min and max to account for overflow
99	            const adjustedScale = adjustScaleForOverflow(min, max, model as CartesianAxisModel, barWidthAndOffset);
100	            min = adjustedScale.min;
101	            max = adjustedScale.max;
102	        }
103	    }
104	
105	    return {
106	        extent: [min, max],
107	        // "fix" means "fixed", the value should not be
108	        // changed in the subsequent steps.
109	        fixMin: rawExtentResult.minFixed,
110	        fixMax: rawExtentResult.maxFixed
111	    };
112	}
113	
114	function adjustScaleForOverflow(
115	    min: number,
116	    max: number,
117	    model: CartesianAxisModel,  // Only support cartesian coord yet.
118	    barWidthAndOffset: BarWidthAndOffset
119	) {
120	
121	    // Get Axis Length
122	    const axisExtent = model.axis.getExtent();
123	    const axisLength = Math.abs(axisExtent[1] - axisExtent[0]);
124	
125	    // Get bars on current base axis and calculate min and max overflow
126	    const barsOnCurrentAxis = retrieveColumnLayout(barWidthAndOffset, model.axis);
127	    if (barsOnCurrentAxis === undefined) {
128	        return {min: min, max: max};
129	    }
130	
131	    let minOverflow = Infinity;
132	    zrUtil.each(barsOnCurrentAxis, function (item) {
133	        minOverflow = Math.min(item.offset, minOverflow);
134	    });
135	    let maxOverflow = -Infinity;
136	    zrUtil.each(barsOnCurrentAxis, function (item) {
137	        maxOverflow = Math.max(item.offset + item.width, maxOverflow);
138	    });
139	    minOverflow = Math.abs(minOverflow);
140	    maxOverflow = Math.abs(maxOverflow);
141	    const totalOverFlow = minOverflow + maxOverflow;
142	
143	    // Calculate required buffer based on old range and overflow
144	    const oldRange = max - min;
145	    const oldRangePercentOfNew = (1 - (minOverflow + maxOverflow) / axisLength);
146	    const overflowBuffer = ((oldRange / oldRangePercentOfNew) - oldRange);
147	
148	    max += overflowBuffer * (maxOverflow / totalOverFlow);
149	    min -= overflowBuffer * (minOverflow / totalOverFlow);
150	
151	    return {min: min, max: max};
152	}
