295	export function ensureScaleRawExtentInfo(
296	    scale: Scale,
297	    model: AxisBaseModel,
298	    // Usually: data extent from all series on this axis.
299	    originalExtent: number[]
300	): ScaleRawExtentInfo {
301	
302	    // Do not permit to recreate.
303	    let rawExtentInfo = scale.rawExtentInfo;
304	    if (rawExtentInfo) {
305	        return rawExtentInfo;
306	    }
307	
308	    rawExtentInfo = new ScaleRawExtentInfo(scale, model, originalExtent);
309	    // @ts-ignore
310	    scale.rawExtentInfo = rawExtentInfo;
311	
312	    return rawExtentInfo;
313	}
